import{_ as a,o as i,c as t,a2 as r}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"TypeScript 知识体系","description":"系统化整理 TypeScript 核心知识,从基础类型到类型体操,再到框架集成与工程配置。","frontmatter":{},"headers":[],"relativePath":"前端/typescript/index.md","filePath":"前端/typescript/index.md","lastUpdated":1793932732000}'),l={name:"前端/typescript/index.md"};function o(c,e,s,n,p,d){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="typescript-知识体系" tabindex="-1">TypeScript 知识体系 <a class="header-anchor" href="#typescript-知识体系" aria-label="Permalink to &quot;TypeScript 知识体系&quot;">​</a></h1><blockquote><p>系统化整理 TypeScript 核心知识,从基础类型到类型体操,再到框架集成与工程配置。</p></blockquote><h2 id="📚-章节列表" tabindex="-1">📚 章节列表 <a class="header-anchor" href="#📚-章节列表" aria-label="Permalink to &quot;📚 章节列表&quot;">​</a></h2><ol><li><a href="./1-basics">基础类型</a> — string / number / boolean / array / tuple / any / void / never / null</li><li><a href="./2-interface">接口</a> — 接口定义 / 继承 / 可选 / 只读 / 函数类型 / 索引签名</li><li><a href="./3-enum">枚举</a> — 数字枚举 / 字符串枚举 / 常量枚举 / 反向映射</li><li><a href="./4-function">函数</a> — 函数类型 / 参数 / 返回值 / 重载 / 泛型函数</li><li><a href="./5-class">类</a> — 字段 / 构造函数 / 继承 / 修饰符 / 抽象类 / 参数属性</li><li><a href="./6-type-guards">类型守卫</a> — typeof / instanceof / 自定义谓词 / 可辨识联合 / asserts</li><li><a href="./7-generic">泛型</a> — 泛型函数 / 接口 / 类 / 约束 / 默认</li><li><a href="./8-advanced">高级类型</a> — 交叉 / 联合 / 类型别名 / keyof / 映射 / 条件 / infer</li><li><a href="./9-utility-types">Utility Types</a> — Partial / Required / Pick / Omit / Record / ReturnType 等</li><li><a href="./10-namespace-module">命名空间与模块</a> — namespace vs module / 导入导出 / 声明合并</li><li><a href="./11-react">React + TypeScript</a> — Props / Hooks / 事件 / 泛型组件 / 常见坑</li><li><a href="./12-vue">Vue + TypeScript</a> — defineComponent / ref 类型 / props 类型 / 模板语法</li><li><a href="./13-tsconfig">tsconfig 配置</a> — target / module / strict / paths / 按场景推荐</li><li><a href="./14-typescript-vs-javascript">TypeScript vs JavaScript</a> — 超集关系、类型系统、迁移策略</li><li><a href="./15-decorator">装饰器</a> — 类 / 方法 / 属性 / 参数装饰器 ⚠️ TS 5 已不推荐,仅作拓展了解</li><li><a href="./16-resources">学习资源</a> — 官方文档 / 练习平台 / 推荐书</li><li><a href="./17-高级类型实战">高级类型实战</a> — <strong>infer / 协变逆变 / satisfies / 模板字面量 / 递归类型 / 真实项目案例</strong></li></ol><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>TS 学习路线:基础类型 → 接口/类型别名 → 泛型 → 高级类型(条件/映射/infer)→ 工具类型 → 框架集成 → tsconfig 工程配置。</li><li>类型系统的核心是<strong>结构化类型</strong>与<strong>类型推导</strong>,理解 <code>extends</code> 的条件类型、<code>infer</code> 的逆类型推导就够应付绝大多数面试题。</li><li>类型体操不是目的:业务里的目标是「让编译器帮你在重构时把错误逼出来」,所以优先用 <code>satisfies</code>、泛型组件、判别联合。</li><li>常见坑:<code>any</code> 滥用导致类型系统失效、<code>strict</code> 没开、第三方类型声明缺失要写 <code>declare module</code>。</li><li>面试加分:讲清 <code>interface</code> vs <code>type</code> 的取舍(对象扩展用 interface,联合/映射用 type)。</li></ul>',6)])])}const u=a(l,[["render",o]]);export{h as __pageData,u as default};
